def median_equal_length(a, b):
    lo1, hi1 = 0, len(a) - 1
    lo2, hi2 = 0, len(b) - 1
    while lo1 < hi1:
        mid1 = (lo1 + hi1) // 2
        mid2 = (lo2 + hi2) // 2
        if a[mid1] == b[mid2]:
            return a[mid1]
        if a[mid1] < b[mid2]:
            if (lo1 + hi1) % 2 == 0:
                lo1 = mid1
                hi2 = mid2
            else:
                lo1 = mid1 + 1
                hi2 = mid2
        else:
            if (lo1 + hi1) % 2 == 0:
                hi1 = mid1
                lo2 = mid2
            else:
                hi1 = mid1
                lo2 = mid2 + 1
    if a[lo1] < b[lo2]:
        return a[lo1]
    return b[lo2]

print(median_equal_length([11, 13, 15, 17, 19], [2, 4, 6, 8, 20]))
print(median_equal_length([1, 3], [2, 4]))
print(median_equal_length([5], [7]))
